<script setup lang="ts">
import { ref } from 'vue'
import type { UserInfo } from '../api'
import { useAdminPage } from '../admin-page'
import { createCards, disableCard, getCards, type MembershipCard, dateTime } from '../growth'
const props = defineProps<{ user: UserInfo }>()
const items = ref<MembershipCard[]>([]), total = ref(0), status = ref(''), days = ref(30), quantity = ref(1), expires = ref(''), generated = ref<string[]>([])
const page = useAdminPage(async valid => { const result = await getCards(status.value); if (valid()) { items.value = result.items; total.value = result.total } }, () => {})
const { error, notice, loading, busy } = page
function load() { void page.load() }
function generate() { void page.act(async valid => { const result = await createCards(props.user.id, Number(days.value), Number(quantity.value), expires.value ? Math.floor(new Date(expires.value).getTime()/1000) : null); if (valid()) { generated.value = result.items.map(item => item.code); notice.value = '卡密已生成，请立即复制保存'; await page.load() } }) }
function disable(id: string) { void page.act(async valid => { await disableCard(props.user.id, id); if (valid()) { notice.value = '卡密已作废'; await page.load() } }) }
</script>
<template><section class="admin-section"><div class="section-toolbar"><p class="text-sm text-muted">生成绑定会员天数的卡密。卡密只在生成时显示一次，兑换后不可重复使用。</p><div class="actions-row"><USelect v-model="status" :items="[{label:'全部',value:''},{label:'可用',value:'active'},{label:'已兑换',value:'redeemed'},{label:'已作废',value:'disabled'}]" /><UButton label="刷新" variant="outline" :loading="loading" @click="load" /></div></div><UAlert v-if="error" :title="error" color="error" class="notice" /><UAlert v-if="notice" :title="notice" color="success" class="notice" /><form class="actions-row card-form" @submit.prevent="generate"><UFormField label="会员天数"><UInput v-model="days" type="number" min="1" max="3660" /></UFormField><UFormField label="生成数量"><UInput v-model="quantity" type="number" min="1" max="1000" /></UFormField><UFormField label="失效日期（可选）"><UInput v-model="expires" type="date" /></UFormField><UButton type="submit" label="生成卡密" :loading="busy" /></form><div v-if="generated.length" class="generated"><strong>本次生成的卡密，请复制保存：</strong><textarea :value="generated.join('\n')" readonly rows="5" /></div><div class="data-scroll"><table class="data-table"><thead><tr><th>卡密尾号</th><th>天数</th><th>状态</th><th>兑换时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>****{{ item.code_hint }}</td><td>{{ item.days }} 天</td><td>{{ item.status === 'active' ? '可用' : item.status === 'redeemed' ? '已兑换' : '已作废' }}</td><td>{{ dateTime(item.redeemed_at) }}</td><td><UButton v-if="item.status === 'active'" label="作废" color="error" variant="soft" @click="disable(item.id)" /></td></tr><tr v-if="!items.length"><td colspan="5">{{ loading ? '正在加载' : '暂无卡密' }}</td></tr></tbody></table></div><p class="text-sm text-muted mt-4">共 {{ total }} 张</p></section></template>
<style scoped>.card-form{align-items:end;margin:20px 0}.generated{padding:14px;margin:14px 0;background:var(--ui-bg-elevated);border-radius:8px}.generated textarea{display:block;width:100%;margin-top:10px;font-family:monospace}</style>
